import React, { useEffect, useState } from 'react'
import "./post-page.css"
import { useParams } from 'react-router-dom'
import UserPostCard from '../../components/postCards/UserPostCard'
import { useDispatch, useSelector } from 'react-redux'
import { getPostStatus, selectPostById, setCreatedPost } from '../../services/post/reducers/postSlice'
import { getCurrentUser } from '../../libs/getCurrentUser'
import { getAllCommentsByPostId } from '../../services/comment/actions/crud/getAllCommentsByPostId'
import { getPostFeedbackError, getPostFeedbackStatus, setPostFeedbackError, updatePostFeebackStatus } from '../../services/comment/reducers/commentPostSlice'
import NotFoundPage from "../../components/notFoundPage/NotFoundPage"
import NetworkError from '../../components/networkError/NetworkError'

const PostPage = () => {
  const {postId} = useParams()
  const post = useSelector(state => selectPostById(state, postId))
  const postFeedbackStatus = useSelector(getPostFeedbackStatus)
  const postFeedbackError = useSelector(getPostFeedbackError)
  const postStatus = useSelector(getPostStatus)

  const dispatch = useDispatch()
  const currentUser = getCurrentUser()
  
  const getAllPostComments = () => {
    try{
      const payload = {
        options: {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${currentUser.userToken}`
          }
        },
        postId
      }
      dispatch(getAllCommentsByPostId(payload))
    }
    catch(error){
      dispatch(setPostFeedbackError(error.message))
    }
    finally{
      dispatch(setPostFeedbackError(null))
    }
  }

  useEffect(() => {
    dispatch(setCreatedPost())
  }, [])

  useEffect(() => {
    getAllPostComments()
  }, [postId, post])

  if(!navigator.onLine){
    return <NetworkError />
  }
  
  if( postFeedbackError && postFeedbackStatus === "failed"){
    dispatch(updatePostFeebackStatus("idle"))
  }

  if(!post && postStatus === "loading" && postFeedbackStatus !== "fulfilled"  && postFeedbackStatus !== "loading"){
    return <>
      <NotFoundPage errorTitle={"Post not found"} />
    </>
  }

  return (
    <section className="post-page-section">
      <UserPostCard posts={post}/>
    </section>
  )
}

export default PostPage
