import React from 'react'
import "./single-post-page.css"
import PostPage from '../../features/postPage/PostPage'
import { useSelector } from 'react-redux';
import { useParams } from 'react-router-dom';
import { getPostStatus, selectPostById } from '../../services/post/reducers/postSlice';
import Loader from '../../components/loader/Loader';

const SinglePostPage = () => {
  const {postId} = useParams()
  const post = useSelector(state => selectPostById(state, postId))
  const postStatus = useSelector(getPostStatus)

  if(postStatus === "loading"){
    return <Loader text={"loading"} />
  }

  const structuredData = JSON.stringify({
    '@context': 'http://schema.org',
    '@type': 'SocialMediaPosting',
    'mainEntityOfPage': {
      '@type': 'WebPage',
      '@id': window.location.href,
    },
    'headline': post?.title,
    'articleBody': post?.post,
    'author': {
      '@type': 'Person',
      'name': post?.user?.username,
    },
    'datePublished': post?.createdAt,
    'dateModified': post?.createdAt,
    'comment': post?.comments?.map(comment => ({
      '@type': 'Comment',
      'author': {
        '@type': 'Person',
        'name': comment?.user.username,
      },
      'text': comment?.comment,
      'datePublished': comment?.createdAt,
    })),
  });

  return (
    <main  itemScope itemType="http://schema.org/SocialMediaPosting">
      <PostPage />
    </main>
  )
}

export default SinglePostPage
